// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title DistributedCacheAuth
 * @notice Cross-service authentication for distributed cache nodes
 * @dev Uses service identity verification with normalized identifiers
 */
contract DistributedCacheAuth {
    struct ServiceNode {
        bytes32 identityHash;
        uint256 registeredAt;
        uint256 lastHeartbeat;
        bool isActive;
        uint8 trustLevel;
    }

    struct CacheEntry {
        bytes value;
        uint256 expiry;
        address owner;
        bytes32 serviceScope;
    }

    mapping(bytes32 => ServiceNode) public serviceRegistry;
    mapping(bytes32 => CacheEntry) public cacheStore;
    mapping(address => bytes32) public addressToService;
    mapping(bytes32 => mapping(bytes32 => bool)) public accessControl;

    address public immutable admin;
    uint256 public constant HEARTBEAT_INTERVAL = 300;
    uint256 public nodeCount;

    event ServiceRegistered(bytes32 indexed serviceId, address indexed registrant);
    event CacheWrite(bytes32 indexed key, bytes32 indexed serviceScope);
    event AccessGranted(bytes32 indexed grantor, bytes32 indexed grantee);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Unauthorized");
        _;
    }

    modifier onlyActiveService() {
        bytes32 svcId = addressToService[msg.sender];
        require(svcId != bytes32(0), "Not registered");
        require(serviceRegistry[svcId].isActive, "Service inactive");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    /**
     * @notice Register a service node with normalized identifier
     * @param serviceIdentifier The UTF-8 encoded service name
     * @param trustLevel Initial trust level (0-255)
     */
    function registerService(
        bytes calldata serviceIdentifier,
        uint8 trustLevel
    ) external onlyAdmin {
        bytes32 normalizedId = _normalizeIdentifier(serviceIdentifier);
        require(serviceRegistry[normalizedId].registeredAt == 0, "Already registered");

        serviceRegistry[normalizedId] = ServiceNode({
            identityHash: keccak256(serviceIdentifier),
            registeredAt: block.timestamp,
            lastHeartbeat: block.timestamp,
            isActive: true,
            trustLevel: trustLevel
        });

        addressToService[msg.sender] = normalizedId;
        nodeCount++;
        emit ServiceRegistered(normalizedId, msg.sender);
    }

    /**
     * @notice Authenticate and bind a caller address to a service
     * @param serviceIdentifier The service name to authenticate as
     * @param authProof Proof of authorization (signed by admin)
     */
    function authenticateAs(
        bytes calldata serviceIdentifier,
        bytes calldata authProof
    ) external {
        bytes32 normalizedId = _normalizeIdentifier(serviceIdentifier);
        require(serviceRegistry[normalizedId].isActive, "Service not active");

        // Verify the auth proof matches the original identity
        bytes32 proofHash = keccak256(abi.encodePacked(
            msg.sender,
            serviceIdentifier,
            block.chainid
        ));
        require(_verifyProof(proofHash, authProof), "Invalid proof");

        addressToService[msg.sender] = normalizedId;
    }

    /**
     * @notice Write to the distributed cache
     */
    function cacheWrite(
        bytes32 key,
        bytes calldata value,
        uint256 ttl
    ) external onlyActiveService {
        bytes32 svcId = addressToService[msg.sender];
        cacheStore[key] = CacheEntry({
            value: value,
            expiry: block.timestamp + ttl,
            owner: msg.sender,
            serviceScope: svcId
        });
        emit CacheWrite(key, svcId);
    }

    /**
     * @notice Read from cache with cross-service auth check
     */
    function cacheRead(bytes32 key) external view onlyActiveService returns (bytes memory) {
        CacheEntry storage entry = cacheStore[key];
        require(entry.expiry > block.timestamp, "Expired");

        bytes32 callerService = addressToService[msg.sender];
        // Allow read if same service scope or explicit access granted
        require(
            entry.serviceScope == callerService ||
            accessControl[entry.serviceScope][callerService],
            "Access denied"
        );

        return entry.value;
    }

    /**
     * @notice Grant cross-service read access
     */
    function grantAccess(bytes32 targetService) external onlyActiveService {
        bytes32 callerService = addressToService[msg.sender];
        require(serviceRegistry[callerService].trustLevel >= 128, "Insufficient trust");
        accessControl[callerService][targetService] = true;
        emit AccessGranted(callerService, targetService);
    }

    /**
     * @dev Normalize a UTF-8 service identifier using NFC-like decomposition
     * @notice This handles Unicode equivalence for service name matching
     * Applies case folding and canonical decomposition to prevent
     * homograph attacks on service identifiers
     */
    function _normalizeIdentifier(bytes calldata identifier) internal pure returns (bytes32) {
        require(identifier.length > 0 && identifier.length <= 64, "Invalid length");

        bytes memory normalized = new bytes(identifier.length);
        uint256 writeIdx = 0;

        for (uint256 i = 0; i < identifier.length; i++) {
            uint8 b = uint8(identifier[i]);

            // ASCII case folding (A-Z -> a-z)
            if (b >= 0x41 && b <= 0x5A) {
                normalized[writeIdx++] = bytes1(b + 0x20);
            }
            // Skip zero-width characters (U+200B-U+200F encoded in UTF-8)
            // UTF-8: E2 80 8B through E2 80 8F
            else if (b == 0xE2 && i + 2 < identifier.length) {
                uint8 b1 = uint8(identifier[i + 1]);
                uint8 b2 = uint8(identifier[i + 2]);
                if (b1 == 0x80 && (b2 >= 0x8B && b2 <= 0x8F)) {
                    i += 2; // Skip the zero-width char
                    continue;
                }
                // Handle soft hyphen (U+00AD) - but this is C2 AD in UTF-8
                normalized[writeIdx++] = bytes1(b);
            }
            // Normalize common confusables: Cyrillic 'а' (D0 B0) -> Latin 'a'
            else if (b == 0xD0 && i + 1 < identifier.length) {
                uint8 b1 = uint8(identifier[i + 1]);
                if (b1 == 0xB0) { // Cyrillic а -> a
                    normalized[writeIdx++] = 0x61;
                    i += 1;
                } else if (b1 == 0xB5) { // Cyrillic е -> e  
                    normalized[writeIdx++] = 0x65;
                    i += 1;
                } else if (b1 == 0xBE) { // Cyrillic о -> o
                    normalized[writeIdx++] = 0x6F;
                    i += 1;
                } else {
                    normalized[writeIdx++] = bytes1(b);
                }
            }
            // Pass through other bytes
            else {
                normalized[writeIdx++] = bytes1(b);
            }
        }

        // Hash the normalized form
        bytes memory result = new bytes(writeIdx);
        for (uint256 j = 0; j < writeIdx; j++) {
            result[j] = normalized[j];
        }
        return keccak256(result);
    }

    /**
     * @dev Verify authorization proof
     */
    function _verifyProof(bytes32 proofHash, bytes calldata proof) internal view returns (bool) {
        if (proof.length != 65) return false;
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(proof.offset)
            s := calldataload(add(proof.offset, 32))
            v := byte(0, calldataload(add(proof.offset, 64)))
        }
        bytes32 ethHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", proofHash));
        address recovered = ecrecover(ethHash, v, r, s);
        return recovered == admin;
    }

    function heartbeat() external onlyActiveService {
        bytes32 svcId = addressToService[msg.sender];
        serviceRegistry[svcId].lastHeartbeat = block.timestamp;
    }

    function deactivateStale(bytes32 serviceId) external {
        ServiceNode storage node = serviceRegistry[serviceId];
        require(node.registeredAt > 0, "Not registered");
        require(
            block.timestamp - node.lastHeartbeat > HEARTBEAT_INTERVAL,
            "Not stale"
        );
        node.isActive = false;
    }
}
